 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, Color } = THREE;

  const visual = config.intent?.visualSpec ?? {};
  const colors = visual.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const group = new Group();

  const atlasRegion = visual.atlasRegion ?? config.atlasRegion;
  let srcW = 512;
  let srcH = 320;
  if (atlasRegion?.sourceRect && atlasRegion.sourceRect.length === 4) {
    srcW = atlasRegion.sourceRect[2];
    srcH = atlasRegion.sourceRect[3];
  }
  const aspect = srcW / srcH || 1.6;
  const planeH = 0.8;
  const planeW = planeH * aspect;

  const gradGeo = new PlaneGeometry(planeW, planeH);
  const gradMat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
  gradMat.colorNode = mix(color(surface), color(ink), smoothstep(0.0, 1.0, uv().y));
  const gradPlane = new Mesh(gradGeo, gradMat);
  gradPlane.position.z = -0.005;
  group.add(gradPlane);

  const planeGeo = new PlaneGeometry(planeW, planeH);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true, side: THREE.DoubleSide });
  planeMat.color.set(paper);
  const plane = new Mesh(planeGeo, planeMat);
  group.add(plane);

  let disposed = false;
  const texUrl = config.imageUrl;
  if (texUrl) {
    ctx.textureLoader.loadTexture(texUrl).then((tex) => {
      if (disposed || !tex) return;
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.needsUpdate = true;
      if (tex.image && atlasRegion?.sourceRect) {
        const [sx, sy, rw, rh] = atlasRegion.sourceRect;
        const aw = tex.image.width || rw;
        const ah = tex.image.height || rh;
        tex.repeat.set(rw / aw, rh / ah);
        tex.offset.set(sx / aw, sy / ah);
      }
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  const items = config.textContent ?? visual.textContent ?? [];
  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : String(item.text ?? '');
    if (!content) continue;
    const fontSize = item.typography?.fontSize ?? (item.role === 'headline' ? 39 : 14);
    const textColor = item.color ?? colors.paper ?? '#e8ecf2';
    const textObj = ctx.fontAtlas.createText(content, {
      fontSize,
      color: textColor,
      align: 'center',
    });
    textObj.position.z = 0.015;
    group.add(textObj);
  }

  const timelines = [];
  const primitiveHandles = [];
  for (const p of config.cinematicPrimitives ?? []) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const result = ctx.primitives[p.name](group, p.params ?? {});
      if (result) primitiveHandles.push(result);
      if (result?.timeline) timelines.push(result.timeline);
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    timelines.forEach((t) => t && t.kill());
    primitiveHandles.forEach((h) => h?.cleanup && h.cleanup());
    gradGeo.dispose();
    gradMat.dispose();
    planeGeo.dispose();
    planeMat.dispose();
    if (planeMat.map) planeMat.map.dispose();
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose());
        else child.material.dispose();
      }
      if (child.userData && typeof child.userData.cleanup === 'function') {
        child.userData.cleanup();
      }
    });
  };

  return group;
}
